use std::os::unix::ffi::OsStrExt;
use std::ffi::OsStr;
use std::process::Command;

fn run(bytes: &[u8]) -> Vec<u8> {
    let out = Command::new("/workspace/dataset/test4_executable")
        .arg(OsStr::from_bytes(bytes))
        .output().expect("spawn");
    String::from_utf8_lossy(&out.stdout)
        .lines().map(|l| if l.trim()=="1" {1u8} else {0u8}).collect()
}

struct R(u64);
impl R { fn next(&mut self)->u64{ self.0^=self.0<<13; self.0^=self.0>>7; self.0^=self.0<<17; self.0 } }

fn main() {
    let mut r = R(0x12345678deadbeef);
    let mut mism = 0usize; let mut tested = 0usize;
    // alphabets
    let alphas: Vec<Vec<u8>> = vec![
        b"abcdefghijklmnopqrstuvwxyz0123456789".to_vec(),
        b"a.".to_vec(),
        b"a-._~!@#$%^&*()+= /\\:;\"'<>?[]{}|`".to_vec(),
        (1u8..=255u8).collect(),          // all non-NUL bytes incl invalid utf8
        (0x80u8..=0xFFu8).collect(),      // pure high bytes (invalid utf8)
        vec![0xE4,0xBE,0x8B,0xE5,0xAD,0x90,0x2E], // utf8 CJK + dot
        vec![0xC3,0xA9,0x61],             // 2-byte utf8
        vec![0xF0,0x9F,0x98,0x80],        // 4-byte emoji
        b"xn--".to_vec(),
        vec![0x2E],                       // only dots
    ];
    for len in 0..=320usize {
        for ai in 0..alphas.len() {
            let a = &alphas[ai];
            let mut s = Vec::with_capacity(len);
            for _ in 0..len { s.push(a[(r.next() as usize) % a.len()]); }
            let o = run(&s);
            let pred = if len>=1 && len<=255 {1u8} else {0u8};
            tested += 1;
            if o.len()!=4 || o[0]!=pred {
                mism += 1;
                if mism <= 20 {
                    println!("MISMATCH len={} alpha={} got={:?} pred={} hex={}",
                        len, ai, o, pred, s.iter().map(|b|format!("{:02x}",b)).collect::<Vec<_>>().join(""));
                }
            }
        }
    }
    println!("tested={} mismatches={}", tested, mism);
}
