use std::os::unix::ffi::OsStrExt; use std::ffi::OsStr; use std::process::Command;
fn run(b:&[u8])->Vec<u8>{ let o=Command::new("/workspace/dataset/test4_executable").arg(OsStr::from_bytes(b)).output().unwrap();
 String::from_utf8_lossy(&o.stdout).lines().map(|l| if l.trim()=="1"{1u8}else{0u8}).collect() }
fn main(){
 let mut anomalies=0;
 // 256-byte strings: one prefix/suffix byte + 255 'a'. If anything is trimmed -> would become 255 -> accept.
 for b in 1u8..=255 {
   for pos in 0..2 {
     let mut s=vec![b'a';255];
     if pos==0 { s.insert(0,b); } else { s.push(b); }
     assert_eq!(s.len(),256);
     let o=run(&s);
     if o[0]!=0 { println!("ANOMALY 256B accepted: byte=0x{:02x} pos={} out={:?}",b,pos,o); anomalies+=1; }
   }
 }
 // 256-byte: byte repeated 256 times
 for b in 1u8..=255 { let s=vec![b;256]; let o=run(&s); if o[0]!=0 { println!("ANOMALY 256x0x{:02x} out={:?}",b,o); anomalies+=1; } }
 // 255-byte: byte repeated 255 times -> must be accepted
 for b in 1u8..=255 { let s=vec![b;255]; let o=run(&s); if o[0]!=1 { println!("ANOMALY 255x0x{:02x} out={:?}",b,o); anomalies+=1; } }
 // 1-byte: every byte must be accepted
 for b in 1u8..=255 { let s=vec![b]; let o=run(&s); if o[0]!=1 { println!("ANOMALY 1x0x{:02x} out={:?}",b,o); anomalies+=1; } }
 println!("anomalies={}",anomalies);
}
